script:
// Carga Histu00f3rica u2014 eventos del panel HTML en Ficha_Cliente
// El HTML estu00e1 en el campo `panel_carga_historica` del DocType.
// Este script solo define la funciu00f3n global ch_importar() que usan los botones.

frappe.ui.form.on('Ficha_Cliente', {
    refresh(frm) {
        if (frm.doc.__islocal) return;
        // Expone la funciu00f3n al scope global para que el onclick del HTML la alcance
        window._ch_frm = frm;
    }
});

window.ch_crear_declaraciones = function() {
    const frm = window._ch_frm;
    if (!frm) return;

    const cliente = frm.doc.name;
    const ano = document.getElementById('ch-ano')?.value;
    const mes = document.getElementById('ch-mes')?.value;

    if (!ano || !mes) {
        frappe.msgprint({ message: 'Selecciona el <b>Au00f1o</b> y <b>Mes</b> antes de continuar.', indicator: 'orange', title: 'Peru00edodo requerido' });
        return;
    }

    const meses_str = ['','Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
    const periodo_label = `${meses_str[parseInt(mes)]} ${ano}`;

    frappe.confirm(
        `u00bfCrear Declaraciu00f3n Mensual + Borrador F29 para <b>${cliente}</b> en <b>${periodo_label}</b>?`,
        () => {
            frappe.show_alert({ message: 'Creando declaraciones...', indicator: 'blue' });
            frappe.call({
                method: 'evoluciona_pyme_v2.evoluciona_pyme_v2.api.crear_declaraciones_periodo',
                args: { cliente, mes, ano },
                callback(r) {
                    const res = r.message || {};
                    if (res.status === 'exists') {
                        frappe.msgprint({ message: `Ya existe una declaraciu00f3n para ${periodo_label}.`, indicator: 'orange', title: 'Ya existe' });
                    } else if (res.status === 'ok') {
                        frappe.msgprint({ message: res.message, indicator: 'green', title: 'Creado' });
                    } else {
                        frappe.msgprint({ message: res.message || 'Error desconocido', indicator: 'red', title: 'Error' });
                    }
                }
            });
        }
    );
};

window.ch_importar = function(tipo) {
    const frm = window._ch_frm;
    if (!frm) return;

    const cliente = frm.doc.name;
    const ano = document.getElementById('ch-ano')?.value;
    const mes = document.getElementById('ch-mes')?.value;

    if (!ano || !mes) {
        frappe.msgprint({ message: 'Selecciona el <b>Au00f1o</b> y <b>Mes</b> antes de importar.', indicator: 'orange', title: 'Peru00edodo requerido' });
        return;
    }

    const meses_str = ['','Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
    const periodo_label = `${meses_str[parseInt(mes)]} ${ano}`;

    if (tipo === 'ventas') {
        const d = new frappe.ui.Dialog({
            title: `Importar Ventas u2014 ${periodo_label}`,
            fields: [
                { fieldtype: 'HTML', options: `<p style="margin-bottom:8px;color:#555;">Cliente: <b>${cliente}</b> | Peru00edodo: <b>${periodo_label}</b></p>` },
                { fieldname: 'file_detalle', fieldtype: 'Attach', label: 'RCV_VENTA (facturas, NC, ND)' },
                { fieldname: 'file_resumen', fieldtype: 'Attach', label: 'RCV_RESUMEN_VENTA (boletas)' },
            ],
            primary_action_label: 'Importar',
            primary_action(vals) {
                if (!vals.file_detalle && !vals.file_resumen) { frappe.msgprint('Sube al menos un archivo.'); return; }
                d.hide();
                frappe.show_alert({ message: 'Importando ventas...', indicator: 'blue' });
                frappe.call({
                    method: 'evoluciona_pyme_v2.evoluciona_pyme_v2.api.importar_libro_ventas_csv',
                    args: { cliente, mes, ano, file_url_detalle: vals.file_detalle || '', file_url_resumen: vals.file_resumen || '' },
                    callback(r) {
                        const res = r.message || {};
                        frappe.msgprint({ message: res.message || 'Error desconocido', indicator: res.status === 'ok' ? 'green' : 'red', title: res.status === 'ok' ? 'Completado' : 'Error' });
                    }
                });
            }
        });
        d.show();
        return;
    }

    const method_map = {
        compras:    'evoluciona_pyme_v2.evoluciona_pyme_v2.api.importar_libro_compras_csv',
        honorarios: 'evoluciona_pyme_v2.evoluciona_pyme_v2.api.importar_libro_honorarios_csv',
        lre:        'evoluciona_pyme_v2.evoluciona_pyme_v2.api.importar_lre_csv',
    };
    const titulo_map = { compras: 'Compras', honorarios: 'Honorarios', lre: 'LRE (Previred)' };

    const d = new frappe.ui.Dialog({
        title: `Importar ${titulo_map[tipo]} u2014 ${periodo_label}`,
        fields: [
            { fieldtype: 'HTML', options: `<p style="margin-bottom:8px;color:#555;">Cliente: <b>${cliente}</b> | Peru00edodo: <b>${periodo_label}</b></p>` },
            { fieldname: 'file_url', fieldtype: 'Attach', label: 'Archivo CSV', reqd: 1 },
        ],
        primary_action_label: 'Importar',
        primary_action(vals) {
            if (!vals.file_url) { frappe.msgprint('Selecciona un archivo.'); return; }
            d.hide();
            frappe.show_alert({ message: `Importando ${titulo_map[tipo]}...`, indicator: 'blue' });
            frappe.call({
                method: method_map[tipo],
                args: { cliente, mes, ano, file_url: vals.file_url },
                callback(r) {
                    const res = r.message || {};
                    frappe.msgprint({ message: res.message || 'Error desconocido', indicator: res.status === 'ok' ? 'green' : 'red', title: res.status === 'ok' ? 'Completado' : 'Error' });
                }
            });
        }
    });
    d.show();
};

frappe.ui.form.on('Test_API', {
    refresh: function(frm) {
        frm.add_custom_button(__('Buscar Producto'), function() {
            
            console.log('Código a buscar:', frm.doc.codigo_producto);
            
            frappe.call({
                method: 'test_api.obtener_datos',
                args: {
                    'codigo_producto': frm.doc.codigo_producto
                },
                callback: function(r) {
                    if (r.message) {
                        frm.set_value('resultado', JSON.stringify(r.message, null, 2));
                        
                        frappe.show_alert({
                            message: r.message.mensaje,
                            indicator: r.message.producto_encontrado ? 'green' : 'orange'
                        }, 5);
                    }
                }
            });
        });
    }
});

frappe.ui.form.on('Test_Calculadora', {
    refresh: function(frm) {
        if (frm.is_new()) return;
        
        frm.add_custom_button(__('Calcular Suma'), function() {
            frappe.call({
                method: 'test_calcular_suma',
                args: { doc_name: frm.doc.name },
                freeze: true,
                freeze_message: __('Calculando...'),
                callback: function(r) {
                    if (r.message && r.message.status === 'ok') {
                        frappe.show_alert({
                            message: 'Suma: $' + r.message.suma,
                            indicator: 'green'
                        }, 3);
                        frm.reload_doc();
                    }
                },
                error: function(r) {
                    console.error('Error:', r);
                    frappe.msgprint('Error al calcular');
                }
            });
        }).addClass('btn-primary');
    }
});
